const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const keyword = $node['Get Top Keywords'].json;
  const serpData = data.serp || data;

  // Detect SERP features
  const features = {
    featured_snippet: false,
    people_also_ask: false,
    local_pack: false,
    knowledge_panel: false,
    video_carousel: false,
    image_pack: false,
    shopping: false,
    news: false,
    sitelinks: false
  };

  // Parse from API response (structure varies by provider)
  if (serpData.serp_features || serpData.features) {
    const sf = serpData.serp_features || serpData.features || [];
    for (const feature of sf) {
      const name = (feature.type || feature.name || feature).toLowerCase();
      if (name.includes('snippet') || name.includes('featured')) features.featured_snippet = true;
      if (name.includes('people') || name.includes('paa') || name.includes('related')) features.people_also_ask = true;
      if (name.includes('local') || name.includes('map')) features.local_pack = true;
      if (name.includes('knowledge')) features.knowledge_panel = true;
      if (name.includes('video')) features.video_carousel = true;
      if (name.includes('image')) features.image_pack = true;
      if (name.includes('shopping') || name.includes('product')) features.shopping = true;
      if (name.includes('news') || name.includes('top stories')) features.news = true;
      if (name.includes('sitelink')) features.sitelinks = true;
    }
  }

  // Check if we own any features
  const domain = $env.COMPANY_DOMAIN || '';
  let ownsFeature = false;
  if (serpData.featured_snippet_url?.includes(domain)) ownsFeature = true;

  const activeFeatures = Object.entries(features).filter(([k, v]) => v).map(([k]) => k);

  results.push({
    json: {
      keyword_id: keyword.id,
      keyword: keyword.keyword,
      features_detected: activeFeatures,
      feature_count: activeFeatures.length,
      owns_featured_snippet: ownsFeature,
      has_local_pack: features.local_pack,
      has_featured_snippet: features.featured_snippet,
      has_paa: features.people_also_ask,
      opportunity: features.featured_snippet && !ownsFeature ? 'featured_snippet' :
                   features.people_also_ask ? 'paa_optimization' :
                   features.local_pack ? 'local_seo' : 'standard'
    }
  });
}

return results;

const allResults = $input.all().map(i => i.json);

// Summary
const summary = {
  total_keywords: allResults.length,
  with_featured_snippet: allResults.filter(r => r.has_featured_snippet).length,
  with_paa: allResults.filter(r => r.has_paa).length,
  with_local_pack: allResults.filter(r => r.has_local_pack).length,
  we_own_snippet: allResults.filter(r => r.owns_featured_snippet).length
};

// Opportunities
const snippetOpportunities = allResults
  .filter(r => r.has_featured_snippet && !r.owns_featured_snippet)
  .map(r => r.keyword);

const localOpportunities = allResults
  .filter(r => r.has_local_pack)
  .map(r => r.keyword);

return [{
  json: {
    summary,
    snippet_opportunities: snippetOpportunities.slice(0, 10),
    local_opportunities: localOpportunities.slice(0, 10),
    all_results: allResults.slice(0, 20),
    checked_at: new Date().toISOString()
  }
}];

